//! Constrained decoding of Hermes-style tool calls.
//!
//! Small models often emit a `<tool_call>` body that is not the JSON object
//! the declared tools accept: doubled braces, a missing required argument, an
//! undeclared tool. [`ToolCallGuard`] watches the generated bytes and, from the
//! moment the model writes `<tool_call>` outside a reasoning block, masks every
//! token that cannot continue
//!
//! ```text
//! {"name": "<declared tool>", "arguments": <object matching that tool's schema>}</tool_call>
//! ```
//!
//! and releases the mask after the closing tag. Text outside a call is never
//! constrained, and templates with another call format never trigger it.
//!
//! The JSON-schema subset is compiled to byte-level rules (alternatives of
//! sequences of byte sets and rule references) and recognized by a pushdown
//! NFA, the scheme llama.cpp's grammar sampler uses. Supported keywords:
//! `type` (also a list), `properties`, `required`, `items`, `enum`, `const`,
//! `anyOf`, and `oneOf`. Properties are emitted in declaration order, required
//! ones always and optional ones optionally; undeclared properties are
//! rejected when a schema declares any. Other keywords are not enforced, and a
//! schema the compiler does not understand accepts any JSON value.

use serde_json::Value as Json;

const OPEN_CALL: &[u8] = b"<tool_call>";
const CLOSE_CALL: &str = "</tool_call>";
const OPEN_THINK: &[u8] = b"<think>";
const CLOSE_THINK: &[u8] = b"</think>";

/// Whitespace bytes allowed between two JSON tokens; bounds a model that would otherwise emit blanks forever.
const MAX_SPACE: usize = 24;
/// Digits allowed after the first of an integer, fraction, or exponent part.
const MAX_DIGITS: usize = 18;
/// Most likely candidates tested before the whole vocabulary is scanned.
const CANDIDATES: usize = 256;

/// Set of byte values.
#[derive(Clone, Copy, PartialEq, Eq)]
struct ByteSet([u64; 4]);

impl ByteSet {
    fn of(bytes: &[u8]) -> Self {
        let mut s = Self([0; 4]);
        for &b in bytes {
            s.0[(b >> 6) as usize] |= 1 << (b & 63);
        }
        s
    }
    fn range(lo: u8, hi: u8) -> Self {
        let mut s = Self([0; 4]);
        for b in lo..=hi {
            s.0[(b >> 6) as usize] |= 1 << (b & 63);
        }
        s
    }
    fn union(mut self, other: Self) -> Self {
        for i in 0..4 {
            self.0[i] |= other.0[i];
        }
        self
    }
    fn has(&self, b: u8) -> bool {
        self.0[(b >> 6) as usize] & (1 << (b & 63)) != 0
    }
}

#[derive(Clone, Copy)]
enum Elem {
    Bytes(ByteSet),
    Rule(u32),
}

/// One alternative: a sequence of elements.
type Seq = Vec<Elem>;

/// Position inside one alternative of one rule.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct Pos {
    rule: u32,
    alt: u32,
    idx: u32,
}

/// Pending positions, innermost last. Every stack kept in a state set is empty
/// (the input so far is a complete match) or has a byte set at its top position.
type Stack = Vec<Pos>;

#[derive(Default)]
struct Rules {
    alts: Vec<Vec<Seq>>,
}

fn lit(text: &str) -> Seq {
    text.bytes().map(|b| Elem::Bytes(ByteSet::of(&[b]))).collect()
}

impl Rules {
    fn add(&mut self, alts: Vec<Seq>) -> u32 {
        self.alts.push(alts);
        (self.alts.len() - 1) as u32
    }

    /// Reserve an index for a rule whose body refers to itself.
    fn reserve(&mut self) -> u32 {
        self.add(Vec::new())
    }

    /// `set` repeated zero to `max` times.
    fn up_to(&mut self, set: ByteSet, max: usize) -> u32 {
        let mut rule = self.add(vec![vec![]]);
        for _ in 0..max {
            rule = self.add(vec![vec![], vec![Elem::Bytes(set), Elem::Rule(rule)]]);
        }
        rule
    }

    /// Push every stack reachable from `stack` without consuming a byte onto `out`.
    fn expand(&self, mut stack: Stack, out: &mut Vec<Stack>) {
        loop {
            let Some(&top) = stack.last() else {
                out.push(stack);
                return;
            };
            let seq = &self.alts[top.rule as usize][top.alt as usize];
            if top.idx as usize == seq.len() {
                stack.pop();
                continue;
            }
            match seq[top.idx as usize] {
                Elem::Bytes(_) => {
                    out.push(stack);
                    return;
                }
                Elem::Rule(r) => {
                    // The caller resumes after the reference; a reference in tail position needs no return frame.
                    stack.pop();
                    if top.idx as usize + 1 < seq.len() {
                        stack.push(Pos { idx: top.idx + 1, ..top });
                    }
                    let n = self.alts[r as usize].len() as u32;
                    for alt in 0..n {
                        let mut next = stack.clone();
                        next.push(Pos { rule: r, alt, idx: 0 });
                        self.expand(next, out);
                    }
                    return;
                }
            }
        }
    }

    fn start(&self, root: u32) -> Vec<Stack> {
        let mut out = Vec::new();
        for alt in 0..self.alts[root as usize].len() as u32 {
            self.expand(vec![Pos { rule: root, alt, idx: 0 }], &mut out);
        }
        dedup(out)
    }

    fn step(&self, states: &[Stack], byte: u8) -> Vec<Stack> {
        let mut out = Vec::new();
        for stack in states {
            let Some(&top) = stack.last() else { continue };
            if let Elem::Bytes(set) = self.alts[top.rule as usize][top.alt as usize][top.idx as usize] {
                if set.has(byte) {
                    let mut next = stack.clone();
                    if let Some(last) = next.last_mut() {
                        last.idx += 1;
                    }
                    self.expand(next, &mut out);
                }
            }
        }
        dedup(out)
    }

    fn accepts(&self, states: &[Stack], bytes: &[u8]) -> bool {
        if bytes.is_empty() {
            return false;
        }
        let mut current = self.step(states, bytes[0]);
        for &b in &bytes[1..] {
            if current.is_empty() {
                return false;
            }
            current = self.step(&current, b);
        }
        !current.is_empty()
    }
}

fn dedup(mut states: Vec<Stack>) -> Vec<Stack> {
    states.sort_unstable();
    states.dedup();
    states
}

/// Compiler from tool declarations to rules.
struct Compiler {
    rules: Rules,
    space: u32,
    string: u32,
    number: u32,
    integer: u32,
    value: u32,
    object: u32,
}

impl Compiler {
    fn new() -> Self {
        let mut rules = Rules::default();
        let space = rules.up_to(ByteSet::of(b" \n\t\r"), MAX_SPACE);

        let hex = ByteSet::range(b'0', b'9').union(ByteSet::range(b'a', b'f')).union(ByteSet::range(b'A', b'F'));
        let escape = rules.add(vec![
            vec![Elem::Bytes(ByteSet::of(b"\"\\/bfnrt"))],
            vec![Elem::Bytes(ByteSet::of(b"u")), Elem::Bytes(hex), Elem::Bytes(hex), Elem::Bytes(hex), Elem::Bytes(hex)],
        ]);
        // Any byte from 0x20 up except the quote and the backslash; multi-byte UTF-8 passes through.
        let mut plain = ByteSet::range(0x20, 0xff);
        plain.0[0] &= !(1 << b'"');
        plain.0[1] &= !(1 << (b'\\' & 63));
        let chars = rules.reserve();
        rules.alts[chars as usize] = vec![
            vec![],
            vec![Elem::Bytes(plain), Elem::Rule(chars)],
            vec![Elem::Bytes(ByteSet::of(b"\\")), Elem::Rule(escape), Elem::Rule(chars)],
        ];
        let string = rules.add(vec![vec![Elem::Bytes(ByteSet::of(b"\"")), Elem::Rule(chars), Elem::Bytes(ByteSet::of(b"\""))]]);

        let digit = ByteSet::range(b'0', b'9');
        let digits = rules.up_to(digit, MAX_DIGITS);
        let sign = rules.add(vec![vec![], lit("-")]);
        let int_body = rules.add(vec![lit("0"), vec![Elem::Bytes(ByteSet::range(b'1', b'9')), Elem::Rule(digits)]]);
        let integer = rules.add(vec![vec![Elem::Rule(sign), Elem::Rule(int_body)]]);
        let frac = rules.add(vec![vec![], vec![Elem::Bytes(ByteSet::of(b".")), Elem::Bytes(digit), Elem::Rule(digits)]]);
        let exp_sign = rules.add(vec![vec![], vec![Elem::Bytes(ByteSet::of(b"+-"))]]);
        let exp_digits = rules.up_to(digit, 2);
        let exp = rules.add(vec![vec![], vec![Elem::Bytes(ByteSet::of(b"eE")), Elem::Rule(exp_sign), Elem::Bytes(digit), Elem::Rule(exp_digits)]]);
        let number = rules.add(vec![vec![Elem::Rule(integer), Elem::Rule(frac), Elem::Rule(exp)]]);

        let value = rules.reserve();
        let object = rules.reserve();
        let array = rules.reserve();
        let mut c = Self { rules, space, string, number, integer, value, object };
        let member = c.rules.add(vec![vec![Elem::Rule(string), Elem::Rule(space), Elem::Bytes(ByteSet::of(b":")), Elem::Rule(space), Elem::Rule(value)]]);
        let object_body = c.list_of(member, b'{', b'}');
        c.rules.alts[object as usize] = object_body;
        let array_body = c.list_of(value, b'[', b']');
        c.rules.alts[array as usize] = array_body;
        c.rules.alts[value as usize] = vec![
            vec![Elem::Rule(object)],
            vec![Elem::Rule(array)],
            vec![Elem::Rule(string)],
            vec![Elem::Rule(number)],
            lit("true"),
            lit("false"),
            lit("null"),
        ];
        c
    }

    /// Alternatives for `open (item (, item)*)? close` with optional whitespace around every token.
    fn list_of(&mut self, item: u32, open: u8, close: u8) -> Vec<Seq> {
        let sp = Elem::Rule(self.space);
        let more = self.rules.reserve();
        self.rules.alts[more as usize] = vec![vec![], vec![Elem::Bytes(ByteSet::of(b",")), sp, Elem::Rule(item), sp, Elem::Rule(more)]];
        vec![
            vec![Elem::Bytes(ByteSet::of(&[open])), sp, Elem::Bytes(ByteSet::of(&[close]))],
            vec![Elem::Bytes(ByteSet::of(&[open])), sp, Elem::Rule(item), sp, Elem::Rule(more), Elem::Bytes(ByteSet::of(&[close]))],
        ]
    }

    fn literal(&mut self, value: &Json) -> u32 {
        self.rules.add(vec![lit(&value.to_string())])
    }

    fn one_of(&mut self, rules: Vec<u32>) -> u32 {
        if rules.len() == 1 {
            return rules[0];
        }
        self.rules.add(rules.into_iter().map(|r| vec![Elem::Rule(r)]).collect())
    }

    /// Rule accepting the JSON values `schema` admits.
    fn schema(&mut self, schema: &Json) -> u32 {
        let Some(map) = schema.as_object() else { return self.value };
        if let Some(c) = map.get("const") {
            return self.literal(c);
        }
        if let Some(values) = map.get("enum").and_then(Json::as_array).filter(|v| !v.is_empty()) {
            let rules = values.iter().map(|v| self.literal(v)).collect();
            return self.one_of(rules);
        }
        if let Some(options) = map.get("anyOf").or_else(|| map.get("oneOf")).and_then(Json::as_array).filter(|v| !v.is_empty()) {
            let rules = options.iter().map(|o| self.schema(o)).collect();
            return self.one_of(rules);
        }
        match map.get("type") {
            Some(Json::String(t)) => self.typed(t, schema),
            Some(Json::Array(types)) if !types.is_empty() => {
                let rules = types.iter().map(|t| t.as_str().map_or(self.value, |t| self.typed(t, schema))).collect();
                self.one_of(rules)
            }
            // A schema that only lists properties describes an object.
            _ if map.contains_key("properties") => self.object_of(schema),
            _ => self.value,
        }
    }

    fn typed(&mut self, kind: &str, schema: &Json) -> u32 {
        match kind {
            "string" => self.string,
            "integer" => self.integer,
            "number" => self.number,
            "boolean" => self.rules.add(vec![lit("true"), lit("false")]),
            "null" => self.rules.add(vec![lit("null")]),
            "array" => {
                let item = schema.get("items").map_or(self.value, |items| self.schema(items));
                let body = self.list_of(item, b'[', b']');
                self.rules.add(body)
            }
            "object" => self.object_of(schema),
            _ => self.value,
        }
    }

    fn object_of(&mut self, schema: &Json) -> u32 {
        let Some(props) = schema.get("properties").and_then(Json::as_object).filter(|p| !p.is_empty()) else {
            return self.object;
        };
        let required: Vec<&str> =
            schema.get("required").and_then(Json::as_array).map(|r| r.iter().filter_map(Json::as_str).collect()).unwrap_or_default();
        let sp = Elem::Rule(self.space);
        let members: Vec<(u32, bool)> = props
            .iter()
            .map(|(key, value)| {
                let value = self.schema(value);
                let mut seq = lit(&Json::String(key.clone()).to_string());
                seq.extend([sp, Elem::Bytes(ByteSet::of(b":")), sp, Elem::Rule(value)]);
                (self.rules.add(vec![seq]), required.contains(&key.as_str()))
            })
            .collect();
        // rest[i][comma]: the members from index i on, given whether one was already written.
        let mut rest = [self.rules.add(vec![vec![]]); 2];
        for &(member, is_required) in members.iter().rev() {
            let next = rest;
            for comma in 0..2 {
                let mut with = Vec::new();
                if comma == 1 {
                    with.extend([Elem::Bytes(ByteSet::of(b",")), sp]);
                }
                with.extend([Elem::Rule(member), sp, Elem::Rule(next[1])]);
                let mut alts = vec![with];
                if !is_required {
                    alts.push(vec![Elem::Rule(next[comma])]);
                }
                rest[comma] = self.rules.add(alts);
            }
        }
        self.rules.add(vec![vec![Elem::Bytes(ByteSet::of(b"{")), sp, Elem::Rule(rest[0]), Elem::Bytes(ByteSet::of(b"}"))]])
    }

    /// Root rule for one call body up to and including the closing tag.
    fn call(&mut self, tools: &[(String, Json)]) -> u32 {
        let sp = Elem::Rule(self.space);
        let mut alts = Vec::new();
        for (name, parameters) in tools {
            let arguments = match parameters.get("type").and_then(Json::as_str) {
                Some("object") | None => self.object_of(parameters),
                Some(_) => self.schema(parameters),
            };
            let mut seq = lit(&Json::String(name.clone()).to_string());
            seq.extend([sp, Elem::Bytes(ByteSet::of(b",")), sp]);
            seq.extend(lit("\"arguments\""));
            seq.extend([sp, Elem::Bytes(ByteSet::of(b":")), sp, Elem::Rule(arguments)]);
            alts.push(seq);
        }
        let tool = self.rules.add(alts);
        let mut root = vec![sp, Elem::Bytes(ByteSet::of(b"{")), sp];
        root.extend(lit("\"name\""));
        root.extend([sp, Elem::Bytes(ByteSet::of(b":")), sp, Elem::Rule(tool), sp, Elem::Bytes(ByteSet::of(b"}")), sp]);
        root.extend(lit(CLOSE_CALL));
        self.rules.add(vec![root])
    }
}

/// Declared tools as `(name, parameters schema)`, read from OpenAI-style declarations.
fn declared(tools: &Json) -> Vec<(String, Json)> {
    tools
        .as_array()
        .map(|list| {
            list.iter()
                .filter_map(|tool| {
                    let function = tool.get("function").unwrap_or(tool);
                    let name = function.get("name")?.as_str()?.to_string();
                    Some((name, function.get("parameters").cloned().unwrap_or(Json::Null)))
                })
                .collect()
        })
        .unwrap_or_default()
}

/// Watches one generation and constrains each `<tool_call>` body to a declared tool and its schema.
pub struct ToolCallGuard {
    rules: Rules,
    root: u32,
    /// Live recognizer states while inside a call body.
    states: Option<Vec<Stack>>,
    /// Recent bytes outside a call, kept to find markers split across tokens.
    tail: Vec<u8>,
    in_reasoning: bool,
}

impl ToolCallGuard {
    /// Build a guard for the declared tools.
    /// @param tools - OpenAI-style tool declarations.
    /// @param opens_reasoning - the prompt ended inside a reasoning block.
    /// @returns `None` when no tool is declared.
    pub fn new(tools: &Json, opens_reasoning: bool) -> Option<Self> {
        let tools = declared(tools);
        if tools.is_empty() {
            return None;
        }
        let mut compiler = Compiler::new();
        let root = compiler.call(&tools);
        Some(Self { rules: compiler.rules, root, states: None, tail: Vec::new(), in_reasoning: opens_reasoning })
    }

    /// Whether the generation is inside a call body.
    pub fn active(&self) -> bool {
        self.states.is_some()
    }

    /// Mask every token that cannot continue the call body; a no-op outside one.
    /// @param logits - next-token logits, modified in place.
    /// @param token_bytes - bytes a token id decodes to.
    /// @param is_end - whether a token id ends generation.
    pub fn constrain(&self, logits: &mut [f32], token_bytes: &dyn Fn(u32) -> Vec<u8>, is_end: &dyn Fn(u32) -> bool) {
        let Some(states) = &self.states else { return };
        let fits = |id: usize| !is_end(id as u32) && self.rules.accepts(states, &token_bytes(id as u32));
        let mut order: Vec<usize> = (0..logits.len()).collect();
        let k = CANDIDATES.min(order.len());
        if k == 0 {
            return;
        }
        order.select_nth_unstable_by(k - 1, |&a, &b| logits[b].total_cmp(&logits[a]));
        let mut allowed: Vec<usize> = order[..k].iter().copied().filter(|&id| fits(id)).collect();
        if allowed.is_empty() {
            // The model's likely tokens all break the call; fall back to any token that fits.
            allowed = order[k..].iter().copied().filter(|&id| fits(id)).collect();
        }
        if allowed.is_empty() {
            return;
        }
        let kept: Vec<(usize, f32)> = allowed.into_iter().map(|id| (id, logits[id])).collect();
        logits.fill(f32::NEG_INFINITY);
        for (id, logit) in kept {
            logits[id] = logit;
        }
    }

    /// Record the bytes of the token just generated.
    /// @param bytes - decoded bytes of that token.
    pub fn advance(&mut self, bytes: &[u8]) {
        let mut rest = bytes;
        while !rest.is_empty() {
            match self.states.take() {
                Some(mut states) => {
                    let mut used = 0;
                    for &b in rest {
                        states = self.rules.step(&states, b);
                        used += 1;
                        if states.is_empty() || states.iter().any(Vec::is_empty) {
                            break;
                        }
                    }
                    // An empty set means unconstrained output broke the call; an empty stack means the call closed.
                    if !states.is_empty() && !states.iter().any(Vec::is_empty) {
                        self.states = Some(states);
                    }
                    rest = &rest[used..];
                }
                None => {
                    self.tail.push(rest[0]);
                    rest = &rest[1..];
                    if self.tail.ends_with(OPEN_THINK) {
                        self.in_reasoning = true;
                    } else if self.tail.ends_with(CLOSE_THINK) {
                        self.in_reasoning = false;
                    } else if self.tail.ends_with(OPEN_CALL) && !self.in_reasoning {
                        self.states = Some(self.rules.start(self.root));
                        self.tail.clear();
                    }
                    if self.tail.len() > 64 {
                        self.tail.drain(..32);
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn tools() -> Json {
        json!([
            { "type": "function", "function": { "name": "bash", "description": "run", "parameters": {
                "type": "object",
                "properties": {
                    "command": { "type": "string" },
                    "description": { "type": "string" },
                    "timeout_ms": { "type": "integer" },
                    "mode": { "enum": ["fast", "safe"] }
                },
                "required": ["command", "description"]
            } } },
            { "type": "function", "function": { "name": "web_search", "parameters": {
                "type": "object",
                "properties": { "queries": { "type": "array", "items": { "type": "string" } } },
                "required": ["queries"]
            } } },
            { "type": "function", "function": { "name": "todo", "parameters": {
                "type": "object",
                "properties": { "items": { "type": "array", "items": {
                    "type": "object",
                    "properties": { "text": { "type": "string" }, "done": { "type": "boolean" }, "weight": { "type": ["number", "null"] } },
                    "required": ["text", "done"]
                } } },
                "required": ["items"]
            } } },
            { "type": "function", "function": { "name": "free", "parameters": { "type": "object" } } }
        ])
    }

    /// Whether the guard, once inside a call, admits `body` byte by byte and ends released.
    fn call_ok(body: &str) -> bool {
        let mut g = ToolCallGuard::new(&tools(), false).unwrap();
        g.advance(b"Let me check.\n<tool_call>");
        assert!(g.active());
        let states = g.states.clone().unwrap();
        let mut current = states;
        for &b in body.as_bytes() {
            current = g.rules.step(&current, b);
            if current.is_empty() {
                return false;
            }
        }
        current.iter().any(Vec::is_empty)
    }

    #[test]
    fn accepts_calls_matching_the_schema() {
        assert!(call_ok(r#"{"name": "bash", "arguments": {"command": "ls -la", "description": "list"}}</tool_call>"#));
        assert!(call_ok("\n{\"name\":\"bash\",\"arguments\":{\"command\":\"echo \\\"hi\\\" \\u00e9 é\",\"description\":\"d\",\"timeout_ms\":-30,\"mode\":\"safe\"}}\n</tool_call>"));
        assert!(call_ok(r#"{"name": "web_search", "arguments": {"queries": ["GGUF file format", "x"]}}</tool_call>"#));
        assert!(call_ok(r#"{"name": "web_search", "arguments": {"queries": []}}</tool_call>"#));
        assert!(call_ok(
            "{\n  \"name\": \"todo\",\n  \"arguments\": {\n    \"items\": [\n      {\"text\": \"a\", \"done\": true, \"weight\": 1.5e3},\n      {\"text\": \"b\", \"done\": false, \"weight\": null}\n    ]\n  }\n}\n</tool_call>"
        ));
        assert!(call_ok(r#"{"name": "free", "arguments": {"anything": [1, {"x": null}], "y": "z"}}</tool_call>"#));
        assert!(call_ok(r#"{"name": "free", "arguments": {}}</tool_call>"#));
    }

    #[test]
    fn rejects_calls_outside_the_schema() {
        // Doubled braces, as Qwen 2.5 copies from its template.
        assert!(!call_ok(r#"{{"name": "web_search", "arguments": {"queries": ["x"]}}}}</tool_call>"#));
        // Undeclared tool.
        assert!(!call_ok(r#"{"name": "rm", "arguments": {}}</tool_call>"#));
        // Missing required property.
        assert!(!call_ok(r#"{"name": "bash", "arguments": {"command": "ls"}}</tool_call>"#));
        // Wrong type, undeclared property, value outside the enum.
        assert!(!call_ok(r#"{"name": "bash", "arguments": {"command": 1, "description": "d"}}</tool_call>"#));
        assert!(!call_ok(r#"{"name": "bash", "arguments": {"command": "x", "description": "d", "extra": 1}}</tool_call>"#));
        assert!(!call_ok(r#"{"name": "bash", "arguments": {"command": "x", "description": "d", "mode": "slow"}}</tool_call>"#));
        // Arguments as a string, a fractional integer, a nested required property missing.
        assert!(!call_ok(r#"{"name": "web_search", "arguments": "{\"queries\": []}"}</tool_call>"#));
        assert!(!call_ok(r#"{"name": "bash", "arguments": {"command": "x", "description": "d", "timeout_ms": 1.5}}</tool_call>"#));
        assert!(!call_ok(r#"{"name": "todo", "arguments": {"items": [{"text": "a"}]}}</tool_call>"#));
        // Raw control character inside a string, and an unterminated body.
        assert!(!call_ok("{\"name\": \"free\", \"arguments\": {\"a\": \"x\ny\"}}</tool_call>"));
        assert!(!call_ok(r#"{"name": "free", "arguments": {}}"#));
    }

    #[test]
    fn bounds_whitespace_runs() {
        let blanks = " ".repeat(MAX_SPACE + 1);
        assert!(!call_ok(&format!("{blanks}{{\"name\": \"free\", \"arguments\": {{}}}}</tool_call>")));
    }

    #[test]
    fn stays_idle_without_a_trigger_and_inside_reasoning() {
        assert!(ToolCallGuard::new(&json!([]), false).is_none());
        let mut g = ToolCallGuard::new(&tools(), true).unwrap();
        g.advance(b"I could write <tool_call> here");
        assert!(!g.active());
        g.advance(b"</think>\n<tool");
        assert!(!g.active());
        g.advance(b"_call>");
        assert!(g.active());
        // The closing tag releases the guard, and a second call triggers it again.
        g.advance(br#"{"name": "free", "arguments": {}}</tool_call>"#);
        assert!(!g.active());
        g.advance(b"\n<tool_call>\n{\"name\"");
        assert!(g.active());
    }

    #[test]
    fn masks_tokens_that_break_the_call() {
        let vocab: Vec<&[u8]> = vec![b"{{", b"{", b"{\"name\"", b"<|im_end|>", b"hello", b" ", b""];
        let mut g = ToolCallGuard::new(&tools(), false).unwrap();
        let bytes = |id: u32| vocab[id as usize].to_vec();
        let is_end = |id: u32| id == 3;
        let mut logits = vec![9.0, 1.0, 0.5, 8.0, 7.0, 0.1, 6.0];
        g.constrain(&mut logits, &bytes, &is_end);
        assert_eq!(logits[0], 9.0, "nothing is masked outside a call");
        g.advance(b"<tool_call>");
        g.constrain(&mut logits, &bytes, &is_end);
        let allowed: Vec<usize> = logits.iter().enumerate().filter(|(_, l)| l.is_finite()).map(|(i, _)| i).collect();
        assert_eq!(allowed, vec![1, 2, 5]);
    }

    #[test]
    fn releases_when_unconstrained_bytes_break_the_call() {
        let mut g = ToolCallGuard::new(&tools(), false).unwrap();
        g.advance(b"<tool_call>not json");
        assert!(!g.active());
    }
}
